<script setup lang="ts">
import { onMounted, ref } from 'vue'

const config = useRuntimeConfig()
const siteUrl = config.public.siteUrl.replace(/\/+$/, '')
const { incident: incidentStatus } = useIncidentStatus()
const menuOpen = ref(false)
const view = ref<'reports' | 'trends' | 'sharing'>('reports')
const motionReady = ref(false)
const views = ['reports', 'trends', 'sharing'] as const
const onTabKeydown = (event: KeyboardEvent) => {
  const currentIndex = views.indexOf(view.value)
  let nextIndex = currentIndex
  if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % views.length
  else if (event.key === 'ArrowLeft') nextIndex = (currentIndex + views.length - 1) % views.length
  else if (event.key === 'Home') nextIndex = 0
  else if (event.key === 'End') nextIndex = views.length - 1
  else return
  event.preventDefault()
  view.value = views[nextIndex]
  document.getElementById(`tab-${view.value}`)?.focus()
}
const accessEmail = 'mailto:vishnu@envsoft.io?subject=Doclyzer%20access%20request&body=Hi%20Doclyzer%20team%2C%0A%0AI%27d%20like%20to%20learn%20about%20access%20to%20Doclyzer.%0A%0A'
const title = 'Doclyzer | Make sense of your blood test history'
const description = 'Bring scattered blood test reports together. Keep originals by person, revisit available results over time, and share a profile with a clinician when you choose.'

useSeoMeta({ title, description, ogTitle: title, ogDescription: description, ogUrl: `${siteUrl}/`, ogType: 'website', twitterCard: 'summary', twitterTitle: title, twitterDescription: description })
useHead({
  link: [{ rel: 'canonical', href: `${siteUrl}/` }],
  script: [{ type: 'application/ld+json', innerHTML: JSON.stringify({ '@context': 'https://schema.org', '@type': 'WebSite', name: 'Doclyzer', url: `${siteUrl}/`, description, publisher: { '@type': 'Organization', name: 'Envsoft Solutions LLP' } }) }],
})

onMounted(() => {
  if (!('IntersectionObserver' in window) || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
  motionReady.value = true
  const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
    if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target) }
  }), { threshold: 0.1 })
  document.querySelectorAll('[data-reveal]').forEach((element) => observer.observe(element))
})
</script>

